#!/usr/bin/env bash
#
# Generates the Go sources for the protobuf definitions into gen/go.
#
# The committed sources were generated with:
#   protoc               v36.2
#   protoc-gen-go        v1.36.12
#   protoc-gen-go-grpc   v1.6.2
#
# The C++ sources for the display service are generated by CMake at build
# time, so they always match the protobuf and gRPC versions installed on the
# Raspberry Pi.

set -euo pipefail

cd "$(dirname "$0")"

module_prefix="github.com/DZDomi/crypto-matrix/proto"

protoc -I models \
       -I services \
       --go_out=. \
       --go-grpc_out=. \
       --go_opt=module="$module_prefix" \
       --go-grpc_opt=module="$module_prefix" \
       models/*.proto \
       services/*.proto

# Dont omit booleans, as false is not shown in responses
sed -i.bak -e '/bool/ s/,omitempty//' gen/go/grpc_models/*.pb.go
rm gen/go/grpc_models/*.bak
